56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
64	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        String address = normalizeAddress(owner.getAddress());
115	        if (address.isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
117	        }
118	        owner.setAddress(address);
119	        if (owner.getEmail() != null) {
120	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
121	            if (!EMAIL_PATTERN.matcher(email).matches()) {
122	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	            }
124	            owner.setEmail(email);
125	        }
126	        String telephone = normalizeTelephone(owner.getTelephone());
127	        if (telephone == null) {
128	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
129	        }
130	        owner.setTelephone(telephone);
131	        LocalDate registrationDate = resolveRegistrationDate(owner.getRegistrationDate());
132	        owner.setRegistrationDate(registrationDate);
133	        if (countOwnersRegisteredOn(LocalDate.now()) >= 100) {
134	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
135	        }
136	        if (isTelephoneInUse(telephone)) {
137	            return new ResponseEntity<>(HttpStatus.CONFLICT);
138	        }
139	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()) && isHouseholdInUse(owner)) {
140	            return new ResponseEntity<>(HttpStatus.CONFLICT);
141	        }
142	        if (countOwnersInCity(owner.getCity()) >= 50) {
143	            return new ResponseEntity<>(HttpStatus.CONFLICT);
144	        }
145	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
146	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), registrationDate));
147	        owner.setHouseholdId(householdId(owner));
148	        owner.setNamesakeCount(countNamesakes(owner));
149	        this.clinicService.saveOwner(owner);
150	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
151	        headers.setLocation(UriComponentsBuilder.newInstance()
152	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
153	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
159	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
160	        if (currentOwner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        currentOwner.setAddress(ownerFieldsDto.getAddress());
164	        currentOwner.setCity(ownerFieldsDto.getCity());
165	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
166	        currentOwner.setLastName(ownerFieldsDto.getLastName());
167	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
168	        String email = ownerFieldsDto.getEmail();
169	        if (email != null) {
170	            email = email.trim().toLowerCase(Locale.ROOT);
171	            if (!EMAIL_PATTERN.matcher(email).matches()) {
172	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
173	            }
174	        }
175	        currentOwner.setEmail(email);
176	        this.clinicService.saveOwner(currentOwner);
177	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Transactional
182	    @Override
183	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
184	        Owner owner = this.clinicService.findOwnerById(ownerId);
185	        if (owner == null) {
186	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	        }
188	        this.clinicService.deleteOwner(owner);
189	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
195	        Owner owner = this.clinicService.findOwnerById(ownerId);
196	        if (owner == null) {
197	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	        }
199	        HttpHeaders headers = new HttpHeaders();
200	        Pet pet = petMapper.toPet(petFieldsDto);
201	        owner.setId(ownerId);
202	        pet.setOwner(owner);
203	        pet.getType().setName(null);
204	        this.clinicService.savePet(pet);
205	        PetDto petDto = petMapper.toPetDto(pet);
206	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
207	            .buildAndExpand(pet.getId()).toUri());
208	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
209	    }
210	
211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Override
213	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
214	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
215	        if (currentOwner != null) {
216	            Pet currentPet = this.clinicService.findPetById(petId);
217	            if (currentPet != null) {
218	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
219	                currentPet.setName(petFieldsDto.getName());
220	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
221	                this.clinicService.savePet(currentPet);
222	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
223	            }
224	        }
225	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	    }
227	
228	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
229	    @Override
230	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
231	        HttpHeaders headers = new HttpHeaders();
232	        Visit visit = visitMapper.toVisit(visitFieldsDto);
233	        Pet pet = new Pet();
234	        pet.setId(petId);
235	        visit.setPet(pet);
236	        this.clinicService.saveVisit(visit);
237	        VisitDto visitDto = visitMapper.toVisitDto(visit);
238	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
239	            .buildAndExpand(visit.getId()).toUri());
240	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
241	    }
242	
243	
244	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
245	    @Override
246	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
247	        Owner owner = this.clinicService.findOwnerById(ownerId);
248	        if (owner != null) {
249	            Pet pet = owner.getPet(petId);
250	            if (pet != null) {
251	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
252	            }
253	        }
254	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	    }
256	
257	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
258	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
259	
260	    /**
261	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
262	     * code are kept when present; otherwise country code '+61' is assumed and a single
263	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
264	     * stripped. The result must be a '+' followed by 8 to 15 digits.
265	     * Returns {@code null} when the number cannot form a valid E.164 value.
266	     */
267	    private static String normalizeTelephone(String telephone) {
268	        if (telephone == null) {
269	            return null;
270	        }
271	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
272	        String e164;
273	        if (cleaned.startsWith("+")) {
274	            e164 = cleaned;
275	        } else {
276	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
277	            e164 = "+61" + national;
278	        }
279	        return E164_PATTERN.matcher(e164).matches() ? e164 : null;
280	    }
281	
282	    /**
283	     * Build the customer code '<CITY3>-<LAST3>-<NNNN>': CITY3 is the upper-cased first three
284	     * letters of {@code city}, LAST3 the upper-cased first three letters of {@code lastName},
285	     * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
286	     * owners already registered in that city (e.g. 'SYD-SMI-0007').
287	     */
288	    private String generateCustomerCode(String city, String lastName) {
289	        String city3 = firstThreeLetters(city);
290	        String last3 = firstThreeLetters(lastName);
291	        int sequence = countOwnersInCity(city) + 1;
292	        return String.format("%s-%s-%04d", city3, last3, sequence);
293	    }
294	
295	    /** The upper-cased first three letters (ignoring non-letters) of {@code value}. */
296	    private static String firstThreeLetters(String value) {
297	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
298	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
299	    }
300	
301	    /**
302	     * The number of existing owners registered in {@code city}, compared case-insensitively
303	     * with collapsed whitespace.
304	     */
305	    private int countOwnersInCity(String city) {
306	        String normalized = normalizeHouseholdField(city);
307	        return (int) this.clinicService.findAllOwners().stream()
308	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
309	            .count();
310	    }
311	
312	    /**
313	     * The effective registration date to store for a new owner: the date supplied on the request
314	     * when present, otherwise the current server date. This single point of resolution is what every
315	     * registration-date-derived value (the stored date, the membership number's year segment) is
316	     * computed from.
317	     */
318	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
319	        return suppliedDate != null ? suppliedDate : LocalDate.now();
320	    }
321	
322	    /**
323	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
324	     * {@code registrationDate} year (e.g. 'SMI-0007-M26').
325	     */
326	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
327	        String yy = String.format("%02d", registrationDate.getYear() % 100);
328	        return customerCode + "-M" + yy;
329	    }
330	
331	    /**
332	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
333	     * last name, compared case-insensitively.
334	     */
335	    private int countNamesakes(Owner owner) {
336	        String firstName = normalizeHouseholdField(owner.getFirstName());
337	        String lastName = normalizeHouseholdField(owner.getLastName());
338	        return (int) this.clinicService.findAllOwners().stream()
339	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
340	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
341	            .count();
342	    }
343	
344	    /** The number of existing owners whose registration date is {@code date}. */
345	    private int countOwnersRegisteredOn(LocalDate date) {
346	        return (int) this.clinicService.findAllOwners().stream()
347	            .filter(existing -> date.equals(existing.getRegistrationDate()))
348	            .count();
349	    }
350	
351	    /** Whether any existing owner already uses the given (E.164) telephone number. */
352	    private boolean isTelephoneInUse(String telephone) {
353	        return this.clinicService.findAllOwners().stream()
354	            .map(Owner::getTelephone)
355	            .filter(existing -> existing != null)
356	            .map(OwnerRestControllerV1::normalizeTelephone)
357	            .filter(existing -> existing != null)
358	            .anyMatch(telephone::equals);
359	    }
360	
361	    /** Common street-type abbreviations expanded during address normalization. */
362	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
363	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
364	
365	    /**
366	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
367	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
368	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
369	     * string when {@code address} is null or blank after normalization.
370	     */
371	    private static String normalizeAddress(String address) {
372	        if (address == null) {
373	            return "";
374	        }
375	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
376	        if (collapsed.isEmpty()) {
377	            return "";
378	        }
379	        StringBuilder sb = new StringBuilder(collapsed.length());
380	        for (String token : collapsed.split(" ")) {
381	            if (sb.length() > 0) {
382	                sb.append(' ');
383	            }
384	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
385	        }
386	        return sb.toString();
387	    }
388	
389	    /**
390	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
391	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
392	     */
