351	    /** Whether any existing owner already uses the given (E.164) telephone number. */
352	    private boolean isTelephoneInUse(String telephone) {
353	        return this.clinicService.findAllOwners().stream()
354	            .map(Owner::getTelephone)
355	            .filter(existing -> existing != null)
356	            .map(OwnerRestControllerV1::normalizeTelephone)
357	            .filter(existing -> existing != null)
358	            .anyMatch(telephone::equals);
359	    }
360	
361	    /** Common street-type abbreviations expanded during address normalization. */
362	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
363	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
364	
365	    /**
366	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
367	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
368	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
369	     * string when {@code address} is null or blank after normalization.
370	     */
371	    private static String normalizeAddress(String address) {
372	        if (address == null) {
373	            return "";
374	        }
375	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
376	        if (collapsed.isEmpty()) {
377	            return "";
378	        }
379	        StringBuilder sb = new StringBuilder(collapsed.length());
380	        for (String token : collapsed.split(" ")) {
381	            if (sb.length() > 0) {
382	                sb.append(' ');
383	            }
384	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
385	        }
386	        return sb.toString();
387	    }
388	
389	    /**
390	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
391	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
392	     */
393	    private static String normalizeHouseholdField(String value) {
394	        if (value == null) {
395	            return "";
396	        }
397	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
398	    }
399	
400	    /**
401	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
402	     * same address compared case-insensitively with collapsed whitespace.
403	     */
404	    private List<Owner> findHousemates(Owner owner) {
405	        String lastName = normalizeHouseholdField(owner.getLastName());
406	        String address = normalizeHouseholdField(owner.getAddress());
407	        return this.clinicService.findAllOwners().stream()
408	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
409	                && normalizeHouseholdField(existing.getAddress()).equals(address))
410	            .toList();
411	    }
412	
413	    /**
414	     * Whether any existing owner already shares the same household as {@code owner}, i.e. has the
415	     * same last name AND the same address compared case-insensitively with collapsed whitespace.
416	     */
417	    private boolean isHouseholdInUse(Owner owner) {
418	        return !findHousemates(owner).isEmpty();
419	    }
420	
421	    /**
422	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
423	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
424	     * deterministically from those normalized fields so housemates always resolve to the same value,
425	     * regardless of registration order.
426	     */
427	    private static String householdId(Owner owner) {
428	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
429	            + normalizeHouseholdField(owner.getAddress());
430	        try {
431	            byte[] digest = MessageDigest.getInstance("SHA-256")
432	                .digest(key.getBytes(StandardCharsets.UTF_8));
433	            StringBuilder sb = new StringBuilder(24);
434	            for (int i = 0; i < 12; i++) {
435	                sb.append(String.format("%02X", digest[i]));
436	            }
437	            return sb.toString();
438	        }
439	        catch (NoSuchAlgorithmException e) {
440	            throw new IllegalStateException("SHA-256 not available", e);
441	        }
442	    }
443	}
